const colors={
  '400':{hex:'#60A5FA',space:'OKLCH',values:['70.7%','0.165','254.6°'],other:[['sRGB',['R','G','B'],['37.65%','64.71%','98.04%']],['Display P3',['R','G','B'],['44.1%','64.0%','95.4%']],['HSL',['H','S','L'],['213.1°','93.9%','67.8%']],['OKLab',['L','a','b'],['70.7%','−0.0438','−0.1591']]]},
  '500':{hex:'#3B82F6',space:'OKLCH',values:['62.3%','0.214','259.8°'],other:[['sRGB',['R','G','B'],['23.14%','50.98%','96.47%']],['Display P3',['R','G','B'],['30.3%','50.3%','93.4%']],['HSL',['H','S','L'],['217.2°','91.2%','59.8%']],['OKLab',['L','a','b'],['62.3%','−0.0379','−0.2106']]]}
};
const tokens=[{id:'blue-400',name:'400',path:'colors / blue / 400',color:'400',layer:'Primitive',ramp:true},{id:'blue-500',name:'500',path:'colors / blue / 500',color:'500',layer:'Primitive',ramp:true},{id:'action',name:'action',path:'semantic / action',color:'500',layer:'Semantic',alias:'colors / blue / 500'}];
let selected='blue-400', returnTrigger=null, savedScroll=0;
const list=document.querySelector('#token-list');
function space(name,labels,values){return `<div class="space"><div class="space-title">${name}</div><div class="coords">${labels.map((label,i)=>`<span><b>${label}</b><i>${values[i]}</i></span>`).join('')}</div></div>`;}
list.innerHTML=tokens.map(t=>{const c=colors[t.color];return `<article class="token-row ${selected===t.id?'is-selected':''}" data-id="${t.id}" aria-label="${t.path}"><div class="identity"><button type="button" class="select-token" aria-pressed="${selected===t.id}" aria-label="Inspect ${t.path}"><strong class="mono">${t.name}</strong><span class="token-path mono">${t.path}</span></button><span class="type-inline">Color · ${t.layer}</span>${t.ramp?`<button type="button" class="ramp-link" aria-label="Open ramp blue from ${t.name}">Ramp · blue <span aria-hidden="true">↗</span></button>`:''}</div><span class="type">Color</span><span class="layer">${t.layer}</span><div class="value"><span class="swatch" style="background:${c.hex}" aria-hidden="true"></span><div class="representations">${t.alias?`<div class="alias-target">Reference → <span class="mono">${t.alias}</span></div>`:''}<div class="hex-alpha"><strong>${c.hex}</strong><span class="muted">Alpha 1</span></div>${space(`${t.alias?'Resolved · ':''}${c.space}`,['L','C','H'],c.values)}<button type="button" class="disclosure" aria-expanded="false" aria-controls="spaces-${t.id}" aria-label="Other color spaces for ${t.path}"><span class="chevron" aria-hidden="true"></span>Other color spaces</button><div id="spaces-${t.id}" class="other-spaces" hidden>${c.other.map(s=>space(...s)).join('')}</div></div></div></article>`;}).join('');
function inspect(id){selected=id;const t=tokens.find(t=>t.id===id),c=colors[t.color];for(const row of list.children){const active=row.dataset.id===id;row.classList.toggle('is-selected',active);row.querySelector('.select-token').setAttribute('aria-pressed',String(active));}document.querySelector('#inspector-title').textContent=t.name;document.querySelector('#inspector-path').textContent=t.path;document.querySelector('#inspector-swatch').style.background=c.hex;document.querySelector('#inspector-facts').innerHTML=`<div><dt>Type</dt><dd>Color</dd></div><div><dt>Layer</dt><dd>${t.layer}</dd></div><div><dt>Value source</dt><dd>${t.alias?'Reference':'Literal color'}</dd></div><div><dt>${t.alias?'Resolved space':'Authored space'}</dt><dd>${c.space}</dd></div>`;}
list.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;const row=button.closest('.token-row');if(button.matches('.select-token'))inspect(row.dataset.id);if(button.matches('.disclosure')){const expanded=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!expanded));document.getElementById(button.getAttribute('aria-controls')).hidden=expanded;}if(button.matches('.ramp-link')){returnTrigger=button;savedScroll=window.scrollY;document.querySelector('#tokens-view').hidden=true;document.querySelector('#ramp-view').hidden=false;document.querySelector('.inspector').hidden=true;document.querySelector('#ramp-title').focus();}});
document.querySelector('#back').addEventListener('click',()=>{document.querySelector('#ramp-view').hidden=true;document.querySelector('#tokens-view').hidden=false;document.querySelector('.inspector').hidden=false;returnTrigger?.focus({preventScroll:true});window.scrollTo(0,savedScroll);});
inspect(selected);
